#include <string.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <rt_sys.h>

/* ===========================================================================
 * FIXED CONFIGURATION (replaces the RTE_Compiler_IO_* macros of
 * RTE_Components.h - here the routing to ITM is decided once and for
 * all in this file, not by the Software Component)
 * ===========================================================================*/
#define IO_STDIN_ENABLE     1   /* stdin  -> ITM (ITM_ReceiveChar)  */
#define IO_STDOUT_ENABLE    1   /* stdout -> ITM (ITM_SendChar)     */
#define IO_STDERR_ENABLE    1   /* stderr -> ITM (ITM_SendChar)     */
#define IO_TTY_ENABLE       1   /* _ttywrch -> ITM (ITM_SendChar)   */

#ifndef STDIN_ECHO
	#define STDIN_ECHO      0       /* STDIN: echo to STDOUT */
#endif
#ifndef STDOUT_CR_LF
	#define STDOUT_CR_LF    0       /* STDOUT: add CR for LF */
#endif
#ifndef STDERR_CR_LF
	#define STDERR_CR_LF    0       /* STDERR: add CR for LF */
#endif


/* ===========================================================================
 * ITM (Instrumentation Trace Macrocell) - unchanged from the original
 * ===========================================================================*/

/* ITM registers */
#define ITM_PORT0_U8          (*((volatile uint8_t  *)0xE0000000))
#define ITM_PORT0_U32         (*((volatile uint32_t *)0xE0000000))
#define ITM_TER               (*((volatile uint32_t *)0xE0000E00))
#define ITM_TCR               (*((volatile uint32_t *)0xE0000E80))

#define ITM_TCR_ITMENA_Msk    (1UL << 0)

/*!< Value that signals that \ref ITM_RxBuffer is ready for the next character. */
#define ITM_RXBUFFER_EMPTY    0x5AA55AA5

/*!< Character receive variable. */
extern
volatile int32_t ITM_RxBuffer;
volatile int32_t ITM_RxBuffer = ITM_RXBUFFER_EMPTY;

/**
 * @brief  Sends one character on ITM port 0 (SWO).
 * @param  ch  character to send.
 * @return The character sent.
 * @note   Waits until the ITM FIFO is ready: if SWO tracing is not enabled
 *         in uVision (ITM port 0, ITMENA, TER, Core Clock 170 MHz) the
 *         function stays blocked here.
 */
int32_t ITM_SendChar (int32_t ch);
/**
 * @brief  Sends one character on ITM port 0 (SWO).
 * @param  ch  character to send.
 * @return The character sent.
 * @note   Waits until the ITM FIFO is ready: if SWO tracing is not enabled
 *         in uVision (ITM port 0, ITMENA, TER, Core Clock 170 MHz) the
 *         function stays blocked here.
 */
int32_t ITM_SendChar (int32_t ch)
{
	if ((ITM_TCR & ITM_TCR_ITMENA_Msk) && /* ITM enabled */
	        (ITM_TER & (1UL << 0)        )) { /* ITM Port #0 enabled */
		while (ITM_PORT0_U32 == 0);
		ITM_PORT0_U8 = (uint8_t)ch;
	}
	return (ch);
}

/**
 * @brief  Reads one character from the ITM port without waiting.
 * @return The character received, or -1 if the FIFO is empty.
 */
int32_t ITM_ReceiveChar (void);
/**
 * @brief  Reads one character from the ITM port without waiting.
 * @return The character received, or -1 if the FIFO is empty.
 */
int32_t ITM_ReceiveChar (void)
{
	int32_t ch = -1;                      /* no character available */

	if (ITM_RxBuffer != ITM_RXBUFFER_EMPTY) {
		ch = ITM_RxBuffer;
		ITM_RxBuffer = ITM_RXBUFFER_EMPTY;  /* ready for next character */
	}

	return (ch);
}


/**
 * @brief  Reads one character from stdin.
 * @return The next character available, or -1 in case of a read error.
 * @note   Blocking read: it waits in a loop until a character is available, so it
 *         never returns -1.
 */#if IO_STDIN_ENABLE
/* Read of one character from stdin: blocking, waits until a character is available. */
static int stdin_getchar (void)
{
	int32_t ch;

	do {
		ch = ITM_ReceiveChar();
	} while (ch == -1);
	return (ch);
}
#endif


/**
 * @brief  Writes one character to stdout, routing it to ITM port 0 (SWO).
 * @param  ch  character to output.
 * @return The character written.
 */#if IO_STDOUT_ENABLE
/* Write to stdout: routes to ITM port 0 (SWO). */
static int stdout_putchar (int ch)
{
	return (ITM_SendChar(ch));
}
#endif


/**
 * @brief  Writes one character to stderr.
 * @param  ch  character to output.
 * @return The character written.
 * @note   Same ITM port as stdout: the separation exists only at C library level.
 */#if IO_STDERR_ENABLE
/* Write to stderr: same ITM port as stdout, kept separate for clarity. */
static int stderr_putchar (int ch)
{
	return (ITM_SendChar(ch));
}
#endif


#ifdef __MICROLIB


#if IO_STDIN_ENABLE
	static int getchar_undo =  0;
	static int getchar_ch   = -1;
#endif


/**
   Writes the character specified by c (converted to an unsigned char) to
   the output stream pointed to by stream, at the position indicated by the
   associated file position indicator (if defined), and advances the
   indicator appropriately. If the file position indicator is not defined,
   the character is appended to the output stream.

  \param[in] c       Character
  \param[in] stream  Stream handle

  \return    The character written. If a write error occurs, the error
             indicator is set and fputc returns EOF.
*/
__attribute__((weak))
/**
 * @brief  stdout hook for the C library.
 * @param  c       character to write.
 * @param  stream  destination stream (not used).
 * @return The character written.
 * @note   With `useUlib=0` the library takes the `_sys_*` branch - this function
 *         remains as a second hook for the variants that use fputc.
 */
int fputc (int c, FILE *stream)
{
#if (!IO_STDOUT_ENABLE && !IO_STDERR_ENABLE)
	(void)c;
	(void)stream;
#endif

#if IO_STDOUT_ENABLE
	if (stream == &__stdout) {
#if (STDOUT_CR_LF != 0)
		if (c == '\n') stdout_putchar('\r');
#endif
		return (stdout_putchar(c));
	}
#endif

#if IO_STDERR_ENABLE
	if (stream == &__stderr) {
#if (STDERR_CR_LF != 0)
		if (c == '\n') stderr_putchar('\r');
#endif
		return (stderr_putchar(c));
	}
#endif

	return (-1);
}


/**
   Obtains the next character (if present) as an unsigned char converted to
   an int, from the input stream pointed to by stream, and advances the
   associated file position indicator (if defined).

  \param[in] stream  Stream handle

  \return    The next character from the input stream pointed to by stream.
             If the stream is at end-of-file, the end-of-file indicator is
             set and fgetc returns EOF. If a read error occurs, the error
             indicator is set and fgetc returns EOF.
*/
__attribute__((weak))
/**
 * @brief  stdin hook for the C library.
 * @param  stream  source stream (not used).
 * @return The character read, or EOF.
 */
int fgetc (FILE *stream)
{
#if IO_STDIN_ENABLE
	int ch;

	if (stream == &__stdin) {
		if (getchar_undo) {
			ch = getchar_ch;
			getchar_ch = -1;
			getchar_undo = 0;
			return (ch);
		}
		ch = stdin_getchar();
#if (STDIN_ECHO != 0)
		stdout_putchar(ch);
#endif
		getchar_ch = ch;
		return (ch);
	}
#else
	(void)stream;
#endif

	return (-1);
}


/**
   The function __backspace() is used by the scanf family of functions, and must
   be re-implemented if you retarget the stdio arrangements at the fgetc() level.

  \param[in] stream  Stream handle

  \return    The value returned by __backspace() is either 0 (success) or EOF
             (failure). It returns EOF only if used incorrectly, for example,
             if no characters have been read from the stream. When used
             correctly, __backspace() must always return 0, because the scanf
             family of functions do not check the error return.
*/
__attribute__((weak))
/* Service required by the C library for terminal input: not supported here. */
int __backspace(FILE *stream);
/* Service required by the C library for terminal input: not supported here. */
int __backspace(FILE *stream)
{

#if IO_STDIN_ENABLE
	if (stream == &__stdin) {
		if (getchar_ch != -1) {
			getchar_undo = 1;
			return (0);
		}
		return (-1);
	}
#else
	(void)stream;
#endif

	return (-1);
}


__attribute__((weak, noreturn))
/**
 * @brief  C library assert handler: reports the error and terminates.
 * @param  expr  failed expression.
 * @param  file  source file.
 * @param  line  line.
 */
void __aeabi_assert (const char *expr, const char *file, int line)
{
	char str[12], *p;

	fputs("*** assertion failed: ", stderr);
	fputs(expr, stderr);
	fputs(", file ", stderr);
	fputs(file, stderr);
	fputs(", line ", stderr);

	p = str + sizeof(str);
	*--p = '\0';
	*--p = '\n';
	while (line > 0) {
		*--p = '0' + (line % 10);
		line /= 10;
	}
	fputs(p, stderr);

	abort();
}


__attribute__((weak))
/**
 * @brief  Abnormal program termination.
 * @note   Never returns to the caller.
 */
void abort(void)
{
	for (;;);
}


#else  /* __MICROLIB */


#if (IO_STDIN_ENABLE || IO_STDOUT_ENABLE || IO_STDERR_ENABLE)
	#define RETARGET_SYS

	/* IO device file handles. */
	#define FH_STDIN    0x8001
	#define FH_STDOUT   0x8002
	#define FH_STDERR   0x8003
	// User defined ...

	/* Standard IO device name defines. */
	const char __stdin_name[]  = ":STDIN";
	const char __stdout_name[] = ":STDOUT";
	const char __stderr_name[] = ":STDERR";

#endif


#ifdef RETARGET_SYS
__attribute__((weak))
/**
 * @brief  Opens a simulated stream for the C library.
 * @param  name      requested name (":tt", ":tt1"... for the console).
 * @param  openmode  opening mode.
 * @return A special handle for stdin/stdout/stderr, or -1 if not handled.
 * @note   The library uses the special handles to determine whether the stream is a terminal.
 */
FILEHANDLE _sys_open (const char *name, int openmode)
{
	(void)openmode;

	if (name == NULL) {
		return (-1);
	}

	if (name[0] == ':') {
		if (strcmp(name, ":STDIN") == 0) {
			return (FH_STDIN);
		}
		if (strcmp(name, ":STDOUT") == 0) {
			return (FH_STDOUT);
		}
		if (strcmp(name, ":STDERR") == 0) {
			return (FH_STDERR);
		}
		return (-1);
	}

	return (-1);
}
#endif


/**
  Defined in rt_sys.h, this function closes a file previously opened
  with _sys_open().

  \param[in] fh File handle

  \return    The return value is 0 if successful. A nonzero value indicates
             an error.
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/**
 * @brief  Closes a simulated stream.
 * @param  fh  handle returned by _sys_open.
 * @return 0 on success.
 */
int _sys_close (FILEHANDLE fh)
{

	switch (fh) {
		case FH_STDIN:
			return (0);
		case FH_STDOUT:
			return (0);
		case FH_STDERR:
			return (0);
	}

	return (-1);
}
#endif


/**
  Defined in rt_sys.h, this function writes the contents of a buffer to a file
  previously opened with _sys_open().

  \param[in] fh   File handle
  \param[in] buf  Data buffer
  \param[in] len  Data length
  \param[in] mode Ignore this parameter

  \return    The return value is either:
             - a positive number representing the number of characters not
               written (so any nonzero return value denotes a failure of
               some sort)
             - a negative number indicating an error.
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/**
 * @brief  Writes to stdout or stderr, routing the bytes to the ITM port (SWO).
 * @param  fh    stream handle.
 * @param  buf   buffer of the bytes to write.
 * @param  len   number of bytes.
 * @param  mode  0 = normal write, 1 = control write.
 * @return 0 on success.
 * @note   This is the branch actually used when the library is built with
 *         `useUlib=0`: every `printf` of the firmware goes through here.
 */
int _sys_write (FILEHANDLE fh, const uint8_t *buf, uint32_t len, int mode)
{
#if (IO_STDOUT_ENABLE || IO_STDERR_ENABLE)
	int ch;
#else
	(void)buf;
	(void)len;
#endif
	(void)mode;

	switch (fh) {
		case FH_STDIN:
			return (-1);
		case FH_STDOUT:
#if IO_STDOUT_ENABLE
			for (; len; len--) {
				ch = *buf++;
#if (STDOUT_CR_LF != 0)
				if (ch == '\n') stdout_putchar('\r');
#endif
				stdout_putchar(ch);
			}
#endif
			return (0);
		case FH_STDERR:
#if IO_STDERR_ENABLE
			for (; len; len--) {
				ch = *buf++;
#if (STDERR_CR_LF != 0)
				if (ch == '\n') stderr_putchar('\r');
#endif
				stderr_putchar(ch);
			}
#endif
			return (0);
	}

	return (-1);
}
#endif


/**
  Defined in rt_sys.h, this function reads the contents of a file into a buffer.

  \param[in] fh   File handle
  \param[in] buf  Data buffer
  \param[in] len  Data length
  \param[in] mode Ignore this parameter

  \return     The return value is one of the following:
              - The number of bytes not read (that is, len - result number of
                bytes were read).
              - An error indication.
              - An EOF indicator. The EOF indication involves the setting of
                0x80000000 in the normal result.
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/**
 * @brief  Reads one character from stdin into buf.
 * @param  fh    stream handle.
 * @param  buf   destination buffer.
 * @param  len   number of bytes requested.
 * @param  mode  0 = normal read.
 * @return Number of bytes NOT read, that is len minus the bytes actually read
 *         (len-1 after one character); 0x80000000 set on EOF or error.
 */
int _sys_read (FILEHANDLE fh, uint8_t *buf, uint32_t len, int mode)
{
#if IO_STDIN_ENABLE
	int ch;
#else
	(void)buf;
	(void)len;
#endif
	(void)mode;

	switch (fh) {
		case FH_STDIN:
#if IO_STDIN_ENABLE
			ch = stdin_getchar();
			if (ch < 0) {
				return ((int)(len | 0x80000000U));
			}
			*buf++ = (uint8_t)ch;
#if (STDIN_ECHO != 0)
			stdout_putchar(ch);
#endif
			len--;
			return ((int)(len));
#else
			return ((int)(len | 0x80000000U));
#endif
		case FH_STDOUT:
			return (-1);
		case FH_STDERR:
			return (-1);
	}

	return (-1);
}
#endif


/**
 * @brief  Writes one character to the console (terminal).
 * @param  ch  character to write.
 * @note   The C library uses it for its own internal messages.
 */#if IO_TTY_ENABLE
__attribute__((weak))
/* Write of one character to the terminal (used for the internal messages of the C library). */
void _ttywrch (int ch)
{
	ITM_SendChar(ch);
}
#endif


/**
  Defined in rt_sys.h, this function determines if a file handle identifies
  a terminal.

  \param[in] fh File handle

  \return    The return value is one of the following values:
             - 0:     There is no interactive device.
             - 1:     There is an interactive device.
             - other: An error occurred.
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/**
 * @brief  Tells whether the stream is a terminal.
 * @param  fh  stream handle.
 * @return 1 if it is a terminal.
 * @note   The library queries it to decide line buffering: answering 1
 *         prevents the output from being held in the buffer.
 */
int _sys_istty (FILEHANDLE fh)
{

	switch (fh) {
		case FH_STDIN:
			return (1);
		case FH_STDOUT:
			return (1);
		case FH_STDERR:
			return (1);
	}

	return (0);
}
#endif


/**
  Defined in rt_sys.h, this function puts the file pointer at offset pos from
  the beginning of the file.

  \param[in] fh  File handle
  \param[in] pos File pointer offset

  \return    The result is:
             - non-negative if no error occurs
             - negative if an error occurs
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/* Seek within the stream: not applicable to a terminal. */
int _sys_seek (FILEHANDLE fh, long pos)
{
	(void)pos;

	switch (fh) {
		case FH_STDIN:
			return (-1);
		case FH_STDOUT:
			return (-1);
		case FH_STDERR:
			return (-1);
	}

	return (-1);
}
#endif


/**
  Defined in rt_sys.h, this function returns the current length of a file.

  \param[in] fh File handle

  \return    This function returns the current length of the file fh,
             or a negative error indicator.
*/
#ifdef RETARGET_SYS
__attribute__((weak))
/* Stream length: not applicable to a terminal. */
long _sys_flen (FILEHANDLE fh)
{

	switch (fh) {
		case FH_STDIN:
			return (0);
		case FH_STDOUT:
			return (0);
		case FH_STDERR:
			return (0);
	}

	return (0);
}
#endif


#endif  /* __MICROLIB */
